-- ETAPA 0.10.1: rollback proposto, NAO executado no Supabase.
-- Restaura a baseline confirmada de zero INSERT/UPDATE por coluna.
-- Nao altera SELECT, USAGE, auth runtime, RLS, dados ou papeis.
BEGIN;
SET LOCAL lock_timeout = '5s';
REVOKE INSERT ("id", "organizationId", "name", "kind", "email", "phone", "taxIdentifier") ON ethos."Owner" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "name", "kind", "email", "phone", "taxIdentifier") ON ethos."Tenant" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "code", "name", "kind", "address") ON ethos."Property" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "propertyId", "code", "name", "isMain", "area") ON ethos."PropertyUnit" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "propertyId", "ownerId", "percentage", "startsOn", "endsOn") ON ethos."PropertyOwnership" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "unitId", "code", "startsOn", "endsOn", "baseRent", "currency", "dueDay") ON ethos."Lease" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "leaseId", "tenantId", "role", "startsOn", "endsOn") ON ethos."LeaseTenant" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "leaseId", "code") ON ethos."Contract" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "leaseId", "successorLeaseId", "startsOn", "endsOn", "newRent") ON ethos."LeaseRenewal" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "leaseId", "effectiveOn", "previousRent", "newRent", "percentage", "indexName") ON ethos."RentAdjustment" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "leaseId", "code", "kind", "competence", "amount") ON ethos."Charge" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "chargeId", "number", "dueOn", "amount") ON ethos."Installment" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "leaseId", "code", "amount", "method", "paidAt") ON ethos."Payment" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "paymentId", "number", "issuedAt", "snapshot") ON ethos."Receipt" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "unitId", "leaseId", "kind", "scheduledAt") ON ethos."Inspection" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "inspectionId", "version", "content") ON ethos."InspectionReport" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "unitId", "leaseId", "title", "description", "category", "priority", "estimatedCost", "actualCost") ON ethos."MaintenanceRequest" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "documentId", "unitId", "caption", "sortOrder", "takenAt") ON ethos."Photo" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "recipientMembershipId", "kind", "title", "message", "payload") ON ethos."Notification" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "timezone", "preferences") ON ethos."OrganizationSettings" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "contractId", "version", "content", "contentHash", "validFrom") ON ethos."ContractVersion" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "paymentId", "installmentId", "amount") ON ethos."PaymentAllocation" FROM ethos_tenant_runtime;
REVOKE INSERT ("id", "organizationId", "kind", "originalName", "mimeType", "storageProvider", "bucket", "objectKey", "sizeBytes", "sha256", "ownerId", "tenantId", "unitId", "contractVersionId", "receiptId", "inspectionReportId", "maintenanceRequestId") ON ethos."Document" FROM ethos_tenant_runtime;
REVOKE UPDATE ("name", "kind", "email", "phone", "taxIdentifier", "archivedAt") ON ethos."Owner" FROM ethos_tenant_runtime;
REVOKE UPDATE ("name", "kind", "email", "phone", "taxIdentifier", "archivedAt") ON ethos."Tenant" FROM ethos_tenant_runtime;
REVOKE UPDATE ("code", "name", "kind", "address", "archivedAt") ON ethos."Property" FROM ethos_tenant_runtime;
REVOKE UPDATE ("code", "name", "isMain", "area", "archivedAt") ON ethos."PropertyUnit" FROM ethos_tenant_runtime;
REVOKE UPDATE ("endsOn") ON ethos."PropertyOwnership" FROM ethos_tenant_runtime;
REVOKE UPDATE ("status", "endedAt") ON ethos."Lease" FROM ethos_tenant_runtime;
REVOKE UPDATE ("endsOn") ON ethos."LeaseTenant" FROM ethos_tenant_runtime;
REVOKE UPDATE ("code", "status") ON ethos."Contract" FROM ethos_tenant_runtime;
REVOKE UPDATE ("status") ON ethos."LeaseRenewal" FROM ethos_tenant_runtime;
REVOKE UPDATE ("status", "appliedAt") ON ethos."RentAdjustment" FROM ethos_tenant_runtime;
REVOKE UPDATE ("code", "kind", "competence", "amount", "status") ON ethos."Charge" FROM ethos_tenant_runtime;
REVOKE UPDATE ("number", "dueOn", "amount") ON ethos."Installment" FROM ethos_tenant_runtime;
REVOKE UPDATE ("status", "reversedAt") ON ethos."Payment" FROM ethos_tenant_runtime;
REVOKE UPDATE ("status", "voidedAt", "voidReason") ON ethos."Receipt" FROM ethos_tenant_runtime;
REVOKE UPDATE ("kind", "scheduledAt", "completedAt") ON ethos."Inspection" FROM ethos_tenant_runtime;
REVOKE UPDATE ("status", "content", "finalizedAt") ON ethos."InspectionReport" FROM ethos_tenant_runtime;
REVOKE UPDATE ("title", "description", "category", "status", "priority", "estimatedCost", "actualCost", "completedAt") ON ethos."MaintenanceRequest" FROM ethos_tenant_runtime;
REVOKE UPDATE ("caption", "sortOrder", "takenAt") ON ethos."Photo" FROM ethos_tenant_runtime;
REVOKE UPDATE ("readAt") ON ethos."Notification" FROM ethos_tenant_runtime;
REVOKE UPDATE ("timezone", "preferences") ON ethos."OrganizationSettings" FROM ethos_tenant_runtime;
REVOKE UPDATE ("name") ON ethos."Organization" FROM ethos_tenant_runtime;
COMMIT;
